package top.aameow.management.mapper;

import java.util.*;
import org.apache.ibatis.annotations.*;

public interface FinanceLedgerMapper {
 String ACCOUNT="a.id,a.name,a.holder,a.account_number accountNumber,cast(a.opening_balance as char) openingBalance,a.active,a.remark,a.version,cast(a.opening_balance+coalesce((select sum(case when t.direction in ('income','transfer_in') then t.amount else -t.amount end) from zj_finance_transaction t where t.account_id=a.id and t.status='posted'),0) as char) balance";
 @Select("<script>select "+ACCOUNT+" from zj_finance_account a <where><if test='name!=null and name!=&quot;&quot;'>and (a.name like concat('%',#{name},'%') or a.account_number like concat('%',#{name},'%'))</if></where> order by a.active desc,a.id desc</script>") List<Map<String,Object>> accounts(Map<String,Object> q);
 @Select("select "+ACCOUNT+" from zj_finance_account a where a.id=#{id}") Map<String,Object> account(Long id);
 @Select("select id,active,version from zj_finance_account where id=#{id} for update") Map<String,Object> lockAccount(Long id);
 @Select("select count(*) from zj_finance_transaction where account_id=#{id}") int accountEntries(Long id);
 @Insert("insert into zj_finance_account(name,holder,account_number,opening_balance,active,remark,created_by,updated_by) values(#{name},#{holder},#{accountNumber},#{openingBalance},#{active},#{remark},#{actor},#{actor})") @Options(useGeneratedKeys=true,keyProperty="id") int addAccount(Map<String,Object> v);
 @Update("update zj_finance_account set name=#{name},holder=#{holder},account_number=#{accountNumber},opening_balance=#{openingBalance},active=#{active},remark=#{remark},version=version+1,updated_by=#{actor},updated_at=now() where id=#{id} and version=#{version}") int editAccount(Map<String,Object> v);
 String FILTER="<where><if test='name!=null and name!=&quot;&quot;'>and (t.purpose like concat('%',#{name},'%') or t.counterparty like concat('%',#{name},'%'))</if><if test='accountId!=null'>and t.account_id=#{accountId}</if><if test='projectId!=null'>and t.project_id=#{projectId}</if><if test='contractId!=null'>and t.contract_id=#{contractId}</if><if test='invoiceId!=null'>and t.invoice_id=#{invoiceId}</if><if test='status!=null and status!=&quot;&quot;'>and t.status=#{status}</if><if test='direction!=null and direction!=&quot;&quot;'>and t.direction=#{direction}</if><if test='dateFrom!=null and dateFrom!=&quot;&quot;'>and t.transaction_date &gt;= #{dateFrom}</if><if test='dateTo!=null and dateTo!=&quot;&quot;'>and t.transaction_date &lt;= #{dateTo}</if></where>";
 String TX="t.id,t.account_id accountId,a.name accountName,t.direction,cast(t.amount as char) amount,date_format(t.transaction_date,'%Y-%m-%d') transactionDate,t.purpose,t.counterparty,t.contract_id contractId,c.contract_name contractName,t.project_id projectId,p.project_name projectName,t.reimbursement_id reimbursementId,t.invoice_id invoiceId,i.invoice_no invoiceNo,t.transfer_group transferGroup,t.files,t.remark,t.status,t.version,t.created_by createdBy,t.created_at createdAt,t.void_reason voidReason,t.void_by voidBy,t.void_at voidAt";
 String TXFROM=" from zj_finance_transaction t join zj_finance_account a on a.id=t.account_id left join zj_contract c on c.id=t.contract_id left join zj_work_project p on p.id=t.project_id left join zj_finance_invoice i on i.id=t.invoice_id ";
 @Select("<script>select "+TX+TXFROM+FILTER+" order by t.transaction_date desc,t.id desc</script>") List<Map<String,Object>> transactions(Map<String,Object> q);
 @Select("select "+TX+TXFROM+" where t.id=#{id}") Map<String,Object> transaction(Long id);
 @Select("select "+TX+TXFROM+" where t.transfer_group=#{group} order by t.id") List<Map<String,Object>> transferDetails(String group);
 @Select("select id,request_hash requestHash from zj_finance_transaction where client_token=#{token}") Map<String,Object> transactionToken(String token);
 @Insert("insert into zj_finance_transaction(client_token,request_hash,account_id,direction,amount,transaction_date,purpose,counterparty,contract_id,project_id,reimbursement_id,invoice_id,transfer_group,files,remark,created_by) values(#{clientToken},#{requestHash},#{accountId},#{direction},#{amount},#{transactionDate},#{purpose},#{counterparty},#{contractId},#{projectId},#{reimbursementId},#{invoiceId},#{transferGroup},#{files},#{remark},#{actor})") @Options(useGeneratedKeys=true,keyProperty="id") int addTransaction(Map<String,Object> v);
 @Select("select id,version,status from zj_finance_transaction where id=#{id} for update") Map<String,Object> lockTransaction(Long id);
 @Select("select id,version,status from zj_finance_transaction where transfer_group=#{group} order by id for update") List<Map<String,Object>> transfer(String group);
 @Update("update zj_finance_transaction set status='void',void_reason=#{reason},void_by=#{actor},void_at=now(),version=version+1 where id=#{id} and version=#{version} and status='posted'") int voidTransaction(Map<String,Object> v);
 @Select("select id,status,project_id projectId,cast(amount as char) amount from zj_reimbursement where id=#{id} for update") Map<String,Object> lockClaim(Long id);
 @Select("select count(*) from zj_finance_transaction where reimbursement_id=#{id} and status='posted'") int claimEntries(Long id);
 @Update("update zj_reimbursement set status=#{status},version=version+1 where id=#{id}") int claimStatus(@Param("id") Long id,@Param("status") String status);
 String INVOICE="i.id,i.invoice_no invoiceNo,i.buyer_name buyerName,i.buyer_tax_id buyerTaxId,i.invoice_type invoiceType,cast(i.amount as char) amount,cast(i.tax_amount as char) taxAmount,date_format(i.invoice_date,'%Y-%m-%d') invoiceDate,i.contract_id contractId,c.contract_name contractName,i.project_id projectId,p.project_name projectName,i.files,i.remark,i.status,i.version,i.created_by createdBy,i.created_at createdAt,i.void_reason voidReason,i.void_by voidBy,i.void_at voidAt,cast(coalesce((select sum(t.amount) from zj_finance_transaction t where t.invoice_id=i.id and t.direction='income' and t.status='posted'),0) as char) receivedAmount";
 @Select("<script>select "+INVOICE+" from zj_finance_invoice i left join zj_contract c on c.id=i.contract_id left join zj_work_project p on p.id=i.project_id <where><if test='name!=null and name!=&quot;&quot;'>and (i.invoice_no like concat('%',#{name},'%') or i.buyer_name like concat('%',#{name},'%'))</if><if test='contractId!=null'>and i.contract_id=#{contractId}</if><if test='projectId!=null'>and i.project_id=#{projectId}</if><if test='status!=null and status!=&quot;&quot;'>and i.status=#{status}</if><if test='dateFrom!=null and dateFrom!=&quot;&quot;'>and i.invoice_date &gt;= #{dateFrom}</if><if test='dateTo!=null and dateTo!=&quot;&quot;'>and i.invoice_date &lt;= #{dateTo}</if></where> order by i.invoice_date desc,i.id desc</script>") List<Map<String,Object>> invoices(Map<String,Object> q);
 @Select("select "+INVOICE+" from zj_finance_invoice i left join zj_contract c on c.id=i.contract_id left join zj_work_project p on p.id=i.project_id where i.id=#{id}") Map<String,Object> invoice(Long id);
 @Select("select id,request_hash requestHash from zj_finance_invoice where client_token=#{token}") Map<String,Object> invoiceToken(String token);
 @Select("select id,status from zj_finance_invoice where id=#{id} for update") Map<String,Object> lockInvoice(Long id);
 @Select("select count(*) from zj_finance_transaction where invoice_id=#{id} and status='posted'") int invoiceEntries(Long id);
 @Insert("insert into zj_finance_invoice(client_token,request_hash,invoice_no,buyer_name,buyer_tax_id,invoice_type,amount,tax_amount,invoice_date,contract_id,project_id,files,remark,created_by) values(#{clientToken},#{requestHash},#{invoiceNo},#{buyerName},#{buyerTaxId},#{invoiceType},#{amount},#{taxAmount},#{invoiceDate},#{contractId},#{projectId},#{files},#{remark},#{actor})") @Options(useGeneratedKeys=true,keyProperty="id") int addInvoice(Map<String,Object> v);
 @Update("update zj_finance_invoice set status='void',void_reason=#{reason},void_by=#{actor},void_at=now(),version=version+1 where id=#{id} and version=#{version} and status='issued'") int voidInvoice(Map<String,Object> v);
 @Select("select id,contract_id contractId,project_name name from zj_work_project where id=#{id}") Map<String,Object> project(Long id);
 @Select("select id from zj_contract_identity where id=#{id}") Long contract(Long id);
 @Select("select id,contract_name name,contract_id code from zj_contract where contract_name like concat('%',#{name},'%') or contract_id like concat('%',#{name},'%') order by id desc limit 30") List<Map<String,Object>> contractOptions(String name);
 @Select("select id,purpose name,cast(amount as char) amount,project_id projectId from zj_reimbursement where status='pending' and purpose like concat('%',#{name},'%') order by id desc limit 30") List<Map<String,Object>> claimOptions(String name);
 String INCOME="coalesce((select sum(t.amount) from zj_finance_transaction t where t.contract_id=c.id and t.direction='income' and t.status='posted'),0)";
 String OUTLAY="coalesce((select sum(t.amount) from zj_finance_transaction t where t.contract_id=c.id and t.direction='expense' and t.status='posted'),0)";
 String BILLED="coalesce((select sum(i.amount) from zj_finance_invoice i where i.contract_id=c.id and i.status='issued'),0)";
 @Select("<script>select c.id,c.contract_name name,c.contract_id code,c.contract_type projectType,c.ownership,c.payment_plan paymentPlan,cast(c.amount as char) amount,cast("+INCOME+" as char) receivedAmount,cast("+OUTLAY+" as char) expenseAmount,cast("+BILLED+" as char) invoicedAmount,cast(c.amount-"+INCOME+" as char) outstandingAmount from zj_contract c <where><if test='name!=null and name!=&quot;&quot;'>and (c.contract_name like concat('%',#{name},'%') or c.contract_id like concat('%',#{name},'%'))</if></where> order by c.id desc</script>") List<Map<String,Object>> contracts(Map<String,Object> q);
 @Select("<script>select p.id,p.project_name name,p.project_no code,p.project_type projectType,p.contract_id contractId,c.contract_name contractName,cast(coalesce((select sum(t.amount) from zj_finance_transaction t where t.project_id=p.id and t.direction='income' and t.status='posted'),0) as char) receivedAmount,cast(coalesce((select sum(t.amount) from zj_finance_transaction t where t.project_id=p.id and t.direction='expense' and t.status='posted'),0) as char) expenseAmount,cast(coalesce((select sum(i.amount) from zj_finance_invoice i where i.project_id=p.id and i.status='issued'),0) as char) invoicedAmount,cast(coalesce((select sum(r.amount) from zj_reimbursement r where r.project_id=p.id and r.status='pending'),0) as char) pendingAmount from zj_work_project p left join zj_contract c on c.id=p.contract_id <where><if test='name!=null and name!=&quot;&quot;'>and (p.project_name like concat('%',#{name},'%') or p.project_no like concat('%',#{name},'%'))</if><if test='contractId!=null'>and p.contract_id=#{contractId}</if></where> order by p.id desc</script>") List<Map<String,Object>> projects(Map<String,Object> q);
 @Select("select cast(coalesce(sum(case when direction='income' then amount else 0 end),0) as char) income,cast(coalesce(sum(case when direction='expense' then amount else 0 end),0) as char) expense from zj_finance_transaction where status='posted'") Map<String,Object> cashSummary();
 @Select("select cast(coalesce(sum(amount),0) as char) amount,count(*) records from zj_finance_invoice where status='issued'") Map<String,Object> invoiceSummary();
 @Select("select date_format(transaction_date,'%Y-%m') month,cast(sum(case when direction='income' then amount else 0 end) as char) income,cast(sum(case when direction='expense' then amount else 0 end) as char) expense from zj_finance_transaction where status='posted' and direction in ('income','expense') group by date_format(transaction_date,'%Y-%m') order by month desc limit 12") List<Map<String,Object>> months();
}
